import numpy as np

def predict_grid(n, center):
    """Prediction model"""
    h_out = n + 1
    grid = np.zeros((h_out, n), dtype=int)

    for r in range(h_out):
        for c in range(n):
            if abs(c - center) == r:
                grid[r, c] = 2
            elif ((r - c) % 4 == 2) and (c > center - r) and (c < center + r) and (r >= 3):
                grid[r, c] = 1

    return grid

# Generate for n=17, center=8
test_result = predict_grid(17, 8)

print("Row-by-row for n=17:")
for r in range(test_result.shape[0]):
    ones = [c for c in range(test_result.shape[1]) if test_result[r,c] == 1]
    twos = [c for c in range(test_result.shape[1]) if test_result[r,c] == 2]
    print(f"Row {r}: 1s at {ones}, 2s at {twos}")

# Also verify against what would happen with NO r>=3 constraint
def predict_no_threshold(n, center):
